"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[8276],{18276:t=>{t.exports=JSON.parse('{"slug":"dorozhnye-stroiteli-prosrochka-kredity-oktyabr-2026","locale":"zh","title":"大型道路建设企业逾期贷款自三月翻倍，接近9十亿卢布","description":"大型道路建设企业的逾期贷款翻倍，接近9十亿卢布。订单缩减与现金流缺口如何冲击承包商。","blocks":[{"id":"b001","kind":"paragraph","text":"全国基础设施企业协会统计了22家大型道路桥梁建设公司的债务，包括Avtoban、Natsproektstroy及Dorogi i Mosty。八月末贷款逾期较三月增长一倍以上，接近9十亿卢布。总债务也在增加：贷款增长11.8%至191十亿卢布，对供应商和分包商应付款增长16%至495十亿。样本中两家公司已进入破产程序。"},{"id":"b002","kind":"paragraph","text":"道路主要由政府采购，订单减少。一月至九月地方基础设施建设支出约1万亿卢布，同比少19.1%。联邦“生活基础设施”和“高效交通体系”项目获得886.8十亿，增加3.1%，但不足抵消地方下降。客户单方面终止了协会成员18份合同，总额80.5十亿卢布。"},{"id":"b003","kind":"paragraph","text":"设想装修师傅先买瓷砖、油漆并付助手工资，房主验收后才付款。客户拖延时，师傅只好刷信用卡买下个订单的材料。拖得越久，利润中付给银行的利息越多，这就是现金流缺口。道路承包商在关键利率14%的环境中靠贷款填缺口，CMWP的帕维尔\xb7雅基姆丘克称实际借款成本明显更高。"},{"id":"b004","kind":"paragraph","text":"银行看到风险，越来越常拒绝该行业企业，即使信用历史良好。失去银行保函同样危险：承包商必须冻结自有资金担保政府合同，或放弃新投标。协会总经理玛丽亚\xb7亚尔马利丘克称其为连锁反应：客户终止合同，银行看到风险，继而拒绝其他公司。协会四月曾预警1–2年内出现破产潮，估计半年后预测已开始实现。"},{"id":"b005","kind":"paragraph","text":"建设背后是预算。联邦前9个月赤字5.2万亿卢布，全年计划上调至7.3万亿。地方也削支出，最先削的是建设和维修，因为公务人员工资及社会补助更难削减。原定2027年增加的基础设施国家项目支出推迟至2028年。全国一月至八月建筑工程量下降2.9%。"},{"id":"b006","kind":"paragraph","text":"对地方居民意味着道路维修和新建可能延误；对从业者意味着欠薪与裁员风险上升。雅基姆丘克预计未来6–9个月逾期继续增加。若2028年支出增长实现，幸存承包商能获得业务；但等待缺口越久，能活到那时的公司越少，道路市场越集中。"},{"id":"b007","kind":"heading","text":"道路建设企业为何欠银行更多钱？"},{"id":"b008","kind":"paragraph","text":"地方在2026年前9个月把基础设施建设支出削减19.1%，客户取消18份共80.5十亿卢布合同，现有合同付款也延迟。承包商靠贷款填缺口，利率14%或更高时偿债愈发困难。"},{"id":"b009","kind":"heading","text":"什么是现金流缺口？"},{"id":"b010","kind":"paragraph","text":"账单现在必须付，工程款以后才到账。公司账面可盈利，却仍无钱发工资、买材料。贷款填补缺口，利息侵蚀利润。"},{"id":"b011","kind":"heading","text":"道路建设危机对普通人有什么影响？"},{"id":"b012","kind":"paragraph","text":"地方道路维修和新建可能拖延，行业岗位面临风险。原定2027年增加的基础设施国家项目支出已推迟至2028年。"}],"sources":[{"label":"道路建设企业陷入债务泥潭","url":"https://www.kommersant.ru/doc/9044152"},{"label":"基础设施建设企业贷款逾期翻倍","url":"https://www.kommersant.ru/doc/9044417"},{"label":"深陷债务","url":"https://lenta.ru/news/2026/10/22/pogryazli-v-dolgah"},{"label":"俄罗斯预算赤字降至5.2万亿卢布","url":"https://ru.themoscowtimes.com/2026/10/09/defitsit-byudzheta-rf-umenshilsya-do-52-trln-r-22-vvp-a208256"},{"label":"三分之二地区将削减建设与环境整治支出","url":"https://ru.themoscowtimes.com/2026/10/03/dve-treti-rossiiskih-regionov-urezhut-rashodi-na-stroitelstvo-i-blagoustroistvo-iz-za-defitsita-byudzheta-a207702"}],"sourceBodySha256":"6a480ee0961bbb53dd585c0158613bf1c2f51eef98dcb29ae725c420947d9032"}')}}]);